mapper.select:
SELECT b.prj_id, AS month,sum(b.sply_amt)::bigint AS confirmed_supply_amt
FROM bill.bill b JOIN prj.prj p ON p.prj_id=b.prj_id
LEFT JOIN prj.bill_stg s ON s.bill_stg_id=b.bill_stg_id
WHERE b.bill_stts_cd='CONFIRM' AND b.prj_id=#{projectId}
  AND  >= #{from} AND  <= #{through}
GROUP BY b.prj_id, ORDER BY month
